import type { RecruitmentStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface RecruitmentStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const recruitmentStatusConfig: Record<RecruitmentStatus, RecruitmentStatusEntry> = {
  available: { label: 'Available', variant: 'success' },
  busy: { label: 'Busy', variant: 'warning' },
  stopped: { label: 'Stopped', variant: 'destructive' },
};

const defaultEntry: RecruitmentStatusEntry = { label: '', variant: 'default' };

export function getRecruitmentStatus(status: RecruitmentStatus): RecruitmentStatusEntry {
  return recruitmentStatusConfig[status] ?? { ...defaultEntry, label: snakeCaseToCapitalizedCase(status) };
}

export const recruitmentStatusOptions: SelectItem<RecruitmentStatus>[] = Object.entries(recruitmentStatusConfig).map(
  ([value, { label }]) => ({ name: label, value: value as RecruitmentStatus })
);
